import 'dart:convert';
import 'dart:typed_data';

import 'package:flutter/material.dart';

/// Compact offline version of the approved ScamShield guardian logo.
class ScamShieldBrandLogo extends StatelessWidget {
  final double size;

  const ScamShieldBrandLogo({super.key, this.size = 54});

  static Uint8List? _bytes;
  static Uint8List get bytes => _bytes ??= base64Decode(_logoBase64);

  @override
  Widget build(BuildContext context) {
    return ClipRRect(
      borderRadius: BorderRadius.circular(size * .22),
      child: Image.memory(
        bytes,
        width: size,
        height: size,
        fit: BoxFit.cover,
        filterQuality: FilterQuality.high,
        gaplessPlayback: true,
        semanticLabel: 'ScamShield African guardian logo',
      ),
    );
  }
}

const String _logoBase64 = '';